/// `base_arg` for a function that cannot be used as a method.
const BASE_NONE: u8 = 0;

/// A row with every field at rest: nameless, argumentless, not a method, not
/// fast, and calling nothing. It is also the table's terminator.
const BLANK: EvalFuncDef = EvalFuncDef {
    name: ptr::null_mut(),
    min_argc: 0,
    max_argc: 0,
    base_arg: BASE_NONE,
    fast: false,
    func: None,
    data: EvalFuncData::None,
};

/// A builtin with a function of its own.
const fn builtin(
    name: &'static CStr,
    min_argc: u8,
    max_argc: u8,
    base_arg: u8,
    func: VimLFunc,
) -> EvalFuncDef {
    EvalFuncDef {
        name: name.as_ptr().cast_mut(),
        min_argc,
        max_argc,
        base_arg,
        func,
        ..BLANK
    }
}

/// The same, for one that may also run during a fast event.
const fn fast(
    name: &'static CStr,
    min_argc: u8,
    max_argc: u8,
    base_arg: u8,
    func: VimLFunc,
) -> EvalFuncDef {
    EvalFuncDef {
        fast: true,
        ..builtin(name, min_argc, max_argc, base_arg, func)
    }
}

/// A libm operation on one Float argument.
const fn float(name: &'static CStr, op: FloatFunc) -> EvalFuncDef {
    EvalFuncDef {
        data: EvalFuncData::Float(op),
        ..builtin(name, 1, 1, 1, Some(float_op_wrapper))
    }
}

/// An API method, called through its row of the RPC handler table.
const fn api(name: &'static CStr, argc: u8, row: usize) -> EvalFuncDef {
    EvalFuncDef {
        data: EvalFuncData::Api(
            (&raw const method_handlers)
                .cast::<MsgpackRpcRequestHandler>()
                .wrapping_add(row),
        ),
        ..builtin(name, argc, argc, BASE_NONE, Some(api_wrapper))
    }
}

/// Copy one generated run of rows into place.
const fn fill(table: &mut [EvalFuncDef], base: usize, part: &[EvalFuncDef]) -> usize {
    let mut i = 0;
    while i < part.len() {
        table[base + i] = part[i];
        i += 1;
    }
    base + part.len()
}

/// Every builtin Vimscript function there is, plus the blank row
/// that ends the table.
pub(crate) static BUILTINS: ConstTable<[EvalFuncDef; 644]> = ConstTable::new(table());

/// The table, spliced together from the generated parts.
const fn table() -> [EvalFuncDef; 644] {
    let mut table = [BLANK; 644];
    let mut base = 0;
    base = fill(&mut table, base, table_1::PART);
    assert!(base == 643);
    table
}
